181→func StatePath(ctx context.Context) (string, error) {
182→	path, err := paths.AbsPath(ctx, filepath.Join(paths.EntireDir, fileName))
183→	if err != nil {
184→		return "", fmt.Errorf("resolve memory-loop path: %w", err)
185→	}
186→	return path, nil
187→}
