189→func LoadState(ctx context.Context) (*State, error) {
190→	path, err := StatePath(ctx)
191→	if err != nil {
192→		return nil, err
193→	}
194→
195→	data, err := os.ReadFile(path) //nolint:gosec // repo-local metadata path
196→	if err != nil {
197→		if os.IsNotExist(err) {
198→			return &State{}, nil
199→		}
200→		return nil, fmt.Errorf("read memory-loop state: %w", err)
201→	}
202→
203→	var disk diskState
204→	if err := json.Unmarshal(data, &disk); err != nil {
205→		return nil, fmt.Errorf("parse memory-loop state: %w", err)
206→	}
207→
208→	state := &State{
209→		Store:         disk.Store,
210→		Snapshot:      disk.Snapshot,
211→		InjectionLogs: disk.InjectionLogs,
212→	}
213→	normalizeStateWithSource(state, disk.Store == nil && disk.Snapshot != nil)
214→	return state, nil
215→}
