227→	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
228→		return fmt.Errorf("create memory-loop directory: %w", err)
229→	}
230→
231→	data, err := jsonutil.MarshalIndentWithNewline(diskState{
232→		Store:         state.Store,
233→		InjectionLogs: state.InjectionLogs,
234→	}, "", "  ")
235→	if err != nil {
236→		return fmt.Errorf("marshal memory-loop state: %w", err)
237→	}
238→	if err := os.WriteFile(path, data, 0o644); err != nil { //nolint:gosec // repo-local metadata path
239→		return fmt.Errorf("write memory-loop state: %w", err)
240→	}
241→	return nil
242→}
