256→func SelectRelevant(snapshot Snapshot, prompt string, now time.Time) []Match {
257→	maxInjected := snapshot.MaxInjected
258→	if maxInjected <= 0 {
259→		maxInjected = DefaultMaxInjected
260→	}
261→
262→	promptTokens := tokenize(prompt)
263→	if len(promptTokens) == 0 {
264→		return nil
265→	}
266→
267→	matches := make([]Match, 0, len(snapshot.Records))
268→	for _, record := range snapshot.Records {
269→		if record.Status != "" && record.Status != StatusActive {
270→			continue
271→		}
272→		score, reason := scoreRecord(record, promptTokens, now)
273→		if score <= 0 {
274→			continue
275→		}
276→		matches = append(matches, Match{
277→			Record: record,
278→			Score:  score,
279→			Reason: reason,
280→		})
281→	}
282→
283→	sort.SliceStable(matches, func(i, j int) bool {
284→		if matches[i].Score != matches[j].Score {
285→			return matches[i].Score > matches[j].Score
286→		}
287→		if matches[i].Record.Strength != matches[j].Record.Strength {
288→			return matches[i].Record.Strength > matches[j].Record.Strength
289→		}
290→		return matches[i].Record.Title < matches[j].Record.Title
291→	})
292→
293→	if len(matches) > maxInjected {
294→		matches = matches[:maxInjected]
295→	}
296→	return matches
297→}
