498→func FormatInjectionBlock(matches []Match) string {
499→	if len(matches) == 0 {
500→		return ""
501→	}
502→
503→	var buf bytes.Buffer
504→	buf.WriteString("Memory For This Repo\n")
505→	for _, match := range matches {
506→		buf.WriteString("- ")
507→		buf.WriteString(strings.TrimSpace(match.Record.Title))
508→		if body := strings.TrimSpace(match.Record.Body); body != "" {
509→			buf.WriteString(": ")
510→			buf.WriteString(body)
511→		}
512→		if why := strings.TrimSpace(match.Record.Why); why != "" {
513→			buf.WriteString(" Why: ")
514→			buf.WriteString(why)
515→		}
516→		buf.WriteByte('\n')
517→		if buf.Len() >= maxInjectionBytes {
518→			break
519→		}
520→	}
521→
522→	out := strings.TrimSpace(buf.String())
523→	if len(out) > maxInjectionBytes {
524→		out = out[:maxInjectionBytes]
525→	}
526→	return out
527→}
