603→func scoreRecord(record MemoryRecord, promptTokens map[string]struct{}, now time.Time) (int, string) {
604→	recordTokens := tokenize(strings.Join([]string{
605→		record.Title,
606→		record.Body,
607→		record.Why,
608→		strings.Join(record.Evidence, " "),
609→	}, " "))
610→	if len(recordTokens) == 0 {
611→		return 0, ""
612→	}
613→
614→	overlap := 0
615→	for token := range promptTokens {
616→		if _, ok := recordTokens[token]; ok {
617→			overlap++
618→		}
619→	}
620→	if overlap == 0 {
621→		return 0, ""
622→	}
623→
624→	score := overlap * 10
625→	switch record.Kind {
626→	case KindRepoRule, KindAgentInstruction:
627→		score += 15
628→	case KindSkillPatch:
629→		score += 4
630→	case KindWorkflowRule, KindAntiPattern, "":
631→	}
632→	score += minInt(record.Strength, 5)
633→
634→	if !record.UpdatedAt.IsZero() && now.After(record.UpdatedAt) {
635→		age := now.Sub(record.UpdatedAt)
636→		if age <= 14*24*time.Hour {
637→			score += 2
638→		}
639→	}
640→
641→	return score, "keyword overlap"
642→}
643→
644→func tokenize(text string) map[string]struct{} {
645→	fields := strings.FieldsFunc(strings.ToLower(text), func(r rune) bool {
646→		return !unicode.IsLetter(r) && !unicode.IsNumber(r)
647→	})
648→	tokens := make(map[string]struct{}, len(fields))
649→	for _, field := range fields {
650→		if len(field) < 3 {
651→			continue
652→		}
653→		if _, ok := stopWords[field]; ok {
654→			continue
655→		}
656→		tokens[field] = struct{}{}
657→	}
658→	return tokens
659→}
660→
661→func minInt(a, b int) int {
662→	if a < b {
663→		return a
664→	}
665→	return b
666→}
667→
668→func fingerprintForRecord(kind Kind, title, body string) string {
669→	base := strings.ToLower(strings.TrimSpace(strings.Join([]string{
670→		string(kind),
671→		strings.TrimSpace(title),
672→		strings.TrimSpace(body),
673→	}, "|")))
674→	if base == "" {
675→		return "memory"
676→	}
677→	var b strings.Builder
678→	lastDash := false
679→	for _, r := range base {
680→		switch {
681→		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
682→			b.WriteRune(r)
683→			lastDash = false
684→		default:
685→			if !lastDash {
686→				b.WriteByte('-')
687→				lastDash = true
688→			}
689→		}
690→	}
691→	out := strings.Trim(b.String(), "-")
692→	if out == "" {
693→		return "memory"
694→	}
695→	return out
696→}
