 15→const DefaultMaxRecords = 20
 16→
 17→type Generator struct {
 18→	Runner *llmcli.Runner
 19→}
 20→
 21→type GenerateInput struct {
 22→	Analysis     improve.PatternAnalysis
 23→	Sessions     []insightsdb.SessionRow
 24→	SourceWindow int
 25→	MaxRecords   int
 26→}
 27→
 28→type generateResponse struct {
 29→	Records []generateRecord `json:"records"`
 30→}
