 32→type generateRecord struct {
 33→	Kind             Kind     `json:"kind"`
 34→	Title            string   `json:"title"`
 35→	Body             string   `json:"body"`
 36→	Why              string   `json:"why"`
 37→	Evidence         []string `json:"evidence"`
 38→	SourceSessionIDs []string `json:"source_session_ids"`
 39→	Confidence       string   `json:"confidence"`
 40→	Strength         int      `json:"strength"`
 41→}
