 43→func (g *Generator) Generate(ctx context.Context, input GenerateInput) ([]MemoryRecord, *llmcli.UsageInfo, error) {
 44→	if g.Runner == nil {
 45→		g.Runner = &llmcli.Runner{}
 46→	}
 47→
 48→	if input.MaxRecords <= 0 {
 49→		input.MaxRecords = DefaultMaxRecords
 50→	}
 51→
 52→	raw, usage, err := g.Runner.Execute(ctx, BuildPrompt(input))
 53→	if err != nil {
 54→		return nil, nil, fmt.Errorf("execute memory-loop prompt: %w", err)
 55→	}
 56→
 57→	var resp generateResponse
 58→	if err := json.Unmarshal([]byte(raw), &resp); err != nil {
 59→		return nil, nil, fmt.Errorf("parse memory-loop JSON: %w", err)
 60→	}
 61→
 62→	return buildGeneratedRecords(resp, input, time.Now().UTC()), usage, nil
 63→}
 64→
 65→func buildGeneratedRecords(resp generateResponse, input GenerateInput, now time.Time) []MemoryRecord {
 66→	seen := make(map[string]struct{})
 67→	records := make([]MemoryRecord, 0, len(resp.Records))
 68→	for _, item := range resp.Records {
 69→		title := strings.TrimSpace(item.Title)
 70→		body := strings.TrimSpace(item.Body)
 71→		if title == "" || body == "" {
 72→			continue
 73→		}
 74→		kind := item.Kind
 75→		if kind == "" {
 76→			kind = KindRepoRule
 77→		}
 78→		key := strings.ToLower(string(kind) + "|" + title + "|" + body)
 79→		if _, ok := seen[key]; ok {
 80→			continue
 81→		}
 82→		seen[key] = struct{}{}
 83→
 84→		record := MemoryRecord{
 85→			ID:               makeRecordID(kind, title),
 86→			Kind:             kind,
 87→			Title:            title,
 88→			Body:             body,
 89→			Why:              strings.TrimSpace(item.Why),
 90→			Evidence:         trimSlice(item.Evidence, 3),
 91→			SourceSessionIDs: trimSlice(item.SourceSessionIDs, input.SourceWindow),
 92→			Confidence:       normalizeConfidence(item.Confidence),
 93→			Strength:         clamp(item.Strength, 1, 5),
 94→			Status:           StatusCandidate,
 95→			Origin:           OriginGenerated,
 96→			Fingerprint:      fingerprintForRecord(kind, title, body),
 97→			CreatedAt:        now,
 98→			UpdatedAt:        now,
 99→		}
100→		records = append(records, record)
101→		if len(records) >= input.MaxRecords {
102→			break
103→		}
104→	}
105→
106→	return records
107→}
