109→func BuildPrompt(input GenerateInput) string {
110→	var sb strings.Builder
111→
112→	fmt.Fprintf(&sb, "Build a compact repo memory snapshot from the last %d AI coding sessions.\n\n", input.SourceWindow)
113→
114→	sb.WriteString("<analysis>\n")
115→	fmt.Fprintf(&sb, "sessions: %d\n", input.Analysis.SessionCount)
116→	for _, signal := range input.Analysis.RepeatedInstructions {
117→		fmt.Fprintf(&sb, "repeated_instruction: %s (%d)\n", signal.Value, signal.Count)
118→		for _, evidence := range trimSlice(signal.Evidence, 3) {
119→			fmt.Fprintf(&sb, "  evidence: %q\n", evidence)
120→		}
121→	}
122→	for _, signal := range input.Analysis.MissingContextSignals {
123→		fmt.Fprintf(&sb, "missing_context: %s (%d)\n", signal.Value, signal.Count)
124→		for _, evidence := range trimSlice(signal.Evidence, 3) {
125→			fmt.Fprintf(&sb, "  evidence: %q\n", evidence)
126→		}
127→	}
128→	for _, signal := range input.Analysis.FailureLoops {
129→		fmt.Fprintf(&sb, "failure_loop: %s (%d)\n", signal.Value, signal.Count)
130→		for _, evidence := range trimSlice(signal.Evidence, 3) {
131→			fmt.Fprintf(&sb, "  evidence: %q\n", evidence)
132→		}
133→	}
134→	for _, opportunity := range input.Analysis.SkillOpportunities {
135→		fmt.Fprintf(&sb, "skill_opportunity: %s (%d)\n", opportunity.SkillName, opportunity.Count)
136→		if opportunity.SkillPath != "" {
137→			fmt.Fprintf(&sb, "  path: %s\n", opportunity.SkillPath)
138→		}
139→		if opportunity.MissingInstruction != "" {
140→			fmt.Fprintf(&sb, "  missing_instruction: %s\n", opportunity.MissingInstruction)
141→		}
142→		for _, friction := range trimSlice(opportunity.Friction, 3) {
143→			fmt.Fprintf(&sb, "  friction: %q\n", friction)
144→		}
145→	}
146→	for _, learning := range trimSlice(input.Analysis.RepoLearnings, 5) {
147→		fmt.Fprintf(&sb, "repo_learning: %s\n", learning)
148→	}
149→	for _, learning := range trimSlice(input.Analysis.WorkflowLearnings, 5) {
150→		fmt.Fprintf(&sb, "workflow_learning: %s\n", learning)
151→	}
152→	sb.WriteString("</analysis>\n\n")
153→
154→	sb.WriteString("<recent_sessions>\n")
155→	for _, session := range input.Sessions {
156→		fmt.Fprintf(&sb, "session: %s agent=%s model=%s\n", session.SessionID, session.Agent, session.Model)
157→		for _, friction := range trimSlice(session.Friction, 3) {
158→			fmt.Fprintf(&sb, "  friction: %q\n", friction)
159→		}
160→		for _, instruction := range session.Facets.RepeatedUserInstructions {
161→			fmt.Fprintf(&sb, "  repeated_instruction: %q\n", instruction.Instruction)
162→		}
163→		for _, signal := range session.Facets.MissingContext {
164→			fmt.Fprintf(&sb, "  missing_context: %q\n", signal.Item)
165→		}
166→		for _, signal := range session.Facets.SkillSignals {
167→			fmt.Fprintf(&sb, "  skill_signal: %s | %s\n", signal.SkillName, signal.MissingInstruction)
168→		}
169→	}
170→	sb.WriteString("</recent_sessions>\n\n")
171→
172→	fmt.Fprintf(&sb, `Return ONLY JSON with this structure:
173→{
174→  "records": [{
175→    "kind": "repo_rule|workflow_rule|agent_instruction|skill_patch|anti_pattern",
176→    "title": "short title",
177→    "body": "one actionable sentence",
178→    "why": "why this memory matters for later sessions",
179→    "evidence": ["short quote"],
180→    "source_session_ids": ["session-id"],
181→    "confidence": "high|medium|low",
182→    "strength": 1
183→  }]
184→}
185→
186→Guidelines:
187→- Distill stable repo-specific lessons, not generic coding advice
188→- Prefer rules the developer would want injected into future Claude sessions
189→- Convert skill-related friction into skill_patch memories when appropriate
190→- Avoid duplicates and avoid one-off incidents without repeated evidence
191→- Return at most %d records
192→`, input.MaxRecords)
193→
194→	return sb.String()
195→}
