197→func makeRecordID(kind Kind, title string) string {
198→	base := strings.ToLower(strings.TrimSpace(title))
199→	var b strings.Builder
200→	lastDash := false
201→	for _, r := range base {
202→		switch {
203→		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
204→			b.WriteRune(r)
205→			lastDash = false
206→		default:
207→			if !lastDash {
208→				b.WriteByte('-')
209→				lastDash = true
210→			}
211→		}
212→	}
213→	slug := strings.Trim(b.String(), "-")
214→	if slug == "" {
215→		slug = "memory"
216→	}
217→	return fmt.Sprintf("%s-%s", kind, slug)
218→}
219→
220→func trimSlice[T any](items []T, limit int) []T {
221→	if limit <= 0 || len(items) <= limit {
222→		return items
223→	}
224→	return items[:limit]
225→}
226→
227→func normalizeConfidence(value string) string {
228→	switch strings.ToLower(strings.TrimSpace(value)) {
229→	case "high", "medium", "low":
230→		return strings.ToLower(strings.TrimSpace(value))
231→	default:
232→		return "medium"
233→	}
234→}
235→
236→func clamp(value, lo, hi int) int {
237→	if value < lo {
238→		return lo
239→	}
240→	if value > hi {
241→		return hi
242→	}
243→	return value
244→}
