447→func frequentMemoryTitles(snapshot *memoryloop.Snapshot, logs []memoryloop.InjectionLog) []string {
448→	if snapshot == nil {
449→		return nil
450→	}
451→	titleByID := make(map[string]string, len(snapshot.Records))
452→	for _, record := range snapshot.Records {
453→		titleByID[record.ID] = record.Title
454→	}
455→	counts := make(map[string]int)
456→	for _, log := range logs {
457→		for _, id := range log.InjectedMemoryIDs {
458→			counts[id]++
459→		}
460→	}
461→
462→	type pair struct {
463→		title string
464→		count int
465→	}
466→	pairs := make([]pair, 0, len(counts))
467→	for id, count := range counts {
468→		pairs = append(pairs, pair{title: titleByID[id], count: count})
469→	}
470→	sort.Slice(pairs, func(i, j int) bool {
471→		if pairs[i].count != pairs[j].count {
472→			return pairs[i].count > pairs[j].count
473→		}
474→		return pairs[i].title < pairs[j].title
475→	})
476→
477→	out := make([]string, 0, len(pairs))
478→	for _, item := range pairs {
479→		if item.title == "" {
480→			continue
481→		}
482→		out = append(out, fmt.Sprintf("%s (%d)", item.title, item.count))
483→	}
484→	return out
485→}
