535→func queryMemoryLoopRows(ctx context.Context, idb *insightsdb.InsightsDB, scope memoryLoopScope, last int) ([]insightsdb.SessionRow, error) {
536→	switch scope.Mode {
537→	case memoryLoopScopeRepo:
538→		rows, err := idb.QueryLastNSessions(ctx, last)
539→		if err != nil {
540→			return nil, fmt.Errorf("query repo-scoped sessions: %w", err)
541→		}
542→		return rows, nil
543→	case memoryLoopScopeBranch:
544→		rows, err := idb.QueryByBranch(ctx, scope.Branch, last)
545→		if err != nil {
546→			return nil, fmt.Errorf("query branch-scoped sessions: %w", err)
547→		}
548→		return rows, nil
549→	case memoryLoopScopeMe:
550→		rows, err := idb.QueryByOwnerEmail(ctx, scope.OwnerEmail, last)
551→		if err != nil {
552→			return nil, fmt.Errorf("query owner-scoped sessions: %w", err)
553→		}
554→		return rows, nil
555→	default:
556→		return nil, fmt.Errorf("unsupported scope mode %q", scope.Mode)
557→	}
558→}
559→
560→func filterMemoryLoopRows(rows []insightsdb.SessionRow, scope memoryLoopScope, limit int) ([]insightsdb.SessionRow, error) {
561→	filtered := make([]insightsdb.SessionRow, 0, len(rows))
562→	for _, row := range rows {
563→		switch scope.Mode {
564→		case memoryLoopScopeRepo:
565→			filtered = append(filtered, row)
566→		case memoryLoopScopeBranch:
567→			if row.Branch == scope.Branch {
568→				filtered = append(filtered, row)
569→			}
570→		case memoryLoopScopeMe:
571→			if strings.EqualFold(row.OwnerEmail, scope.OwnerEmail) {
572→				filtered = append(filtered, row)
573→			}
574→		default:
575→			return nil, fmt.Errorf("unsupported scope mode %q", scope.Mode)
576→		}
577→	}
578→
579→	sort.SliceStable(filtered, func(i, j int) bool {
580→		return filtered[i].CreatedAt.After(filtered[j].CreatedAt)
581→	})
582→	if limit > 0 && len(filtered) > limit {
583→		filtered = filtered[:limit]
584→	}
585→	return filtered, nil
586→}
587→
588→func scopeValue(scope memoryLoopScope) string {
589→	switch scope.Mode {
590→	case memoryLoopScopeRepo:
591→		return ""
592→	case memoryLoopScopeBranch:
593→		return scope.Branch
594→	case memoryLoopScopeMe:
595→		return scope.OwnerEmail
596→	default:
597→		return ""
598→	}
599→}
