143→// GetMemoryLoopConfig returns memory-loop configuration with defaults applied.
144→func (s *EntireSettings) GetMemoryLoopConfig() MemoryLoopConfig {
145→	cfg := MemoryLoopConfig{
146→		MaxInjected:          3,
147→		DefaultRefreshWindow: 20,
148→		Mode:                 "off",
149→		ActivationPolicy:     "review",
150→	}
151→	if s.MemoryLoopConfig == nil {
152→		return cfg
153→	}
154→	if s.MemoryLoopConfig.Mode != "" {
155→		cfg.Enabled = true
156→		cfg.Mode = s.MemoryLoopConfig.Mode
157→	} else {
158→		cfg.Enabled = s.MemoryLoopConfig.Enabled
159→	}
160→	if s.MemoryLoopConfig.ActivationPolicy != "" {
161→		cfg.ActivationPolicy = s.MemoryLoopConfig.ActivationPolicy
162→	}
163→	if s.MemoryLoopConfig.Mode == "" && s.MemoryLoopConfig.ClaudeInjectionEnabled != nil {
164→		switch {
165→		case !cfg.Enabled:
166→			cfg.Mode = "off"
167→		case *s.MemoryLoopConfig.ClaudeInjectionEnabled:
168→			cfg.Mode = "auto"
169→		default:
170→			cfg.Mode = "manual"
171→		}
172→	}
173→	if s.MemoryLoopConfig.MaxInjected != 0 {
174→		cfg.MaxInjected = s.MemoryLoopConfig.MaxInjected
175→	}
176→	if s.MemoryLoopConfig.DefaultRefreshWindow != 0 {
177→		cfg.DefaultRefreshWindow = s.MemoryLoopConfig.DefaultRefreshWindow
178→	}
179→	if cfg.MaxInjected == 0 {
180→		cfg.MaxInjected = 3
181→	}
182→	if cfg.DefaultRefreshWindow == 0 {
183→		cfg.DefaultRefreshWindow = 20
184→	}
185→	return cfg
186→}
