198→// Load loads the Entire settings from .entire/settings.json,
199→// then applies any overrides from .entire/settings.local.json if it exists.
200→// Returns default settings if neither file exists.
201→// Works correctly from any subdirectory within the repository.
202→func Load(ctx context.Context) (*EntireSettings, error) {
203→	// Get absolute paths for settings files
204→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
205→	if err != nil {
206→		settingsFileAbs = EntireSettingsFile // Fallback to relative
207→	}
208→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
209→	if err != nil {
210→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
211→	}
212→
213→	// Load base settings
214→	settings, err := loadFromFile(settingsFileAbs)
215→	if err != nil {
216→		return nil, fmt.Errorf("reading settings file: %w", err)
217→	}
218→
219→	// Apply local overrides if they exist
220→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
221→	if err != nil {
222→		if !os.IsNotExist(err) {
223→			return nil, fmt.Errorf("reading local settings file: %w", err)
224→		}
225→		// Local file doesn't exist, continue without overrides
226→	} else {
227→		if err := mergeJSON(settings, localData); err != nil {
228→			return nil, fmt.Errorf("merging local settings: %w", err)
229→		}
230→	}
231→
232→	if err := validateSettings(settings); err != nil {
233→		return nil, err
234→	}
235→
236→	return settings, nil
237→}
238→
239→// LoadFromFile loads settings from a specific file path without merging local overrides.
240→// Returns default settings if the file doesn't exist.
241→// Use this when you need to display individual settings files separately.
242→func LoadFromFile(filePath string) (*EntireSettings, error) {
243→	return loadFromFile(filePath)
244→}
245→
246→// loadFromFile loads settings from a specific file path.
247→// Returns default settings if the file doesn't exist.
248→func loadFromFile(filePath string) (*EntireSettings, error) {
249→	settings := &EntireSettings{
250→		Enabled: true, // Default to enabled
251→	}
252→
253→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
254→	if err != nil {
255→		if os.IsNotExist(err) {
256→			return settings, nil
257→		}
258→		return nil, fmt.Errorf("%w", err)
259→	}
260→
261→	dec := json.NewDecoder(bytes.NewReader(data))
262→	dec.DisallowUnknownFields()
263→	if err := dec.Decode(settings); err != nil {
264→		return nil, fmt.Errorf("parsing settings file: %w", err)
265→	}
266→
267→	// Validate commit_linking if set
268→	if err := validateSettings(settings); err != nil {
269→		return nil, err
270→	}
271→
272→	return settings, nil
273→}
274→
275→// mergeJSON merges JSON data into existing settings.
276→// Only non-zero values from the JSON override existing settings.
277→func mergeJSON(settings *EntireSettings, data []byte) error {
278→	// First, validate that there are no unknown keys using strict decoding
279→	dec := json.NewDecoder(bytes.NewReader(data))
280→	dec.DisallowUnknownFields()
281→	var temp EntireSettings
282→	if err := dec.Decode(&temp); err != nil {
283→		return fmt.Errorf("parsing JSON: %w", err)
284→	}
285→
286→	// Parse into a map to check which fields are present
287→	var raw map[string]json.RawMessage
288→	if err := json.Unmarshal(data, &raw); err != nil {
289→		return fmt.Errorf("parsing JSON: %w", err)
290→	}
291→
292→	// Override enabled if present
293→	if enabledRaw, ok := raw["enabled"]; ok {
294→		var e bool
295→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
296→			return fmt.Errorf("parsing enabled field: %w", err)
297→		}
298→		settings.Enabled = e
299→	}
300→
301→	// Override local_dev if present
302→	if localDevRaw, ok := raw["local_dev"]; ok {
303→		var ld bool
304→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
305→			return fmt.Errorf("parsing local_dev field: %w", err)
306→		}
307→		settings.LocalDev = ld
308→	}
309→
310→	// Override absolute_git_hook_path if present
311→	if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
312→		var ahp bool
313→		if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
314→			return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
315→		}
316→		settings.AbsoluteGitHookPath = ahp
317→	}
318→
319→	// Override log_level if present and non-empty
320→	if logLevelRaw, ok := raw["log_level"]; ok {
321→		var ll string
322→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
323→			return fmt.Errorf("parsing log_level field: %w", err)
324→		}
325→		if ll != "" {
326→			settings.LogLevel = ll
327→		}
328→	}
329→
330→	// Merge strategy_options if present
331→	if optionsRaw, ok := raw["strategy_options"]; ok {
332→		var opts map[string]any
333→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
334→			return fmt.Errorf("parsing strategy_options field: %w", err)
335→		}
336→		if settings.StrategyOptions == nil {
337→			settings.StrategyOptions = opts
338→		} else {
339→			for k, v := range opts {
340→				settings.StrategyOptions[k] = v
341→			}
342→		}
343→	}
344→
345→	// Override telemetry if present
346→	if telemetryRaw, ok := raw["telemetry"]; ok {
347→		var t bool
348→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
349→			return fmt.Errorf("parsing telemetry field: %w", err)
350→		}
351→		settings.Telemetry = &t
352→	}
353→
354→	// Merge redaction sub-fields if present (field-level, not wholesale replace).
355→	if redactionRaw, ok := raw["redaction"]; ok {
356→		if settings.Redaction == nil {
357→			settings.Redaction = &RedactionSettings{}
358→		}
359→		if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
360→			return fmt.Errorf("parsing redaction field: %w", err)
361→		}
362→	}
363→
364→	// Override commit_linking if present and non-empty
365→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
366→		var cl string
367→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
368→			return fmt.Errorf("parsing commit_linking field: %w", err)
369→		}
370→		if cl != "" {
371→			switch cl {
372→			case CommitLinkingAlways, CommitLinkingPrompt:
373→				settings.CommitLinking = cl
374→			default:
375→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
376→			}
377→		}
378→	}
379→
380→	// Override external_agents if present
381→	if externalAgentsRaw, ok := raw["external_agents"]; ok {
382→		var ea bool
383→		if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
384→			return fmt.Errorf("parsing external_agents field: %w", err)
385→		}
386→		settings.ExternalAgents = ea
387→	}
388→
389→	// Override evolve if present
390→	if evolveRaw, ok := raw["evolve"]; ok {
391→		var ev EvolveSettings
392→		if err := json.Unmarshal(evolveRaw, &ev); err != nil {
393→			return fmt.Errorf("parsing evolve field: %w", err)
394→		}
395→		settings.EvolveConfig = &ev
396→	}
