411→func validateSettings(settings *EntireSettings) error {
412→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
413→		return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
414→	}
415→	if settings.MemoryLoopConfig == nil {
416→		return nil
417→	}
418→	if settings.MemoryLoopConfig.Mode != "" {
419→		switch settings.MemoryLoopConfig.Mode {
420→		case "off", "manual", "auto":
421→		default:
