451→			return fmt.Errorf("parsing memory_loop.mode: %w", err)
452→		}
453→		dst.Mode = mode
454→	}
455→	if policyRaw, ok := raw["activation_policy"]; ok {
456→		var policy string
457→		if err := json.Unmarshal(policyRaw, &policy); err != nil {
458→			return fmt.Errorf("parsing memory_loop.activation_policy: %w", err)
459→		}
460→		dst.ActivationPolicy = policy
461→	}
462→	if injectionRaw, ok := raw["claude_injection_enabled"]; ok {
463→		var enabled bool
464→		if err := json.Unmarshal(injectionRaw, &enabled); err != nil {
465→			return fmt.Errorf("parsing memory_loop.claude_injection_enabled: %w", err)
466→		}
467→		dst.ClaudeInjectionEnabled = &enabled
468→	}
469→	if maxInjectedRaw, ok := raw["max_injected"]; ok {
470→		var maxInjected int
471→		if err := json.Unmarshal(maxInjectedRaw, &maxInjected); err != nil {
472→			return fmt.Errorf("parsing memory_loop.max_injected: %w", err)
473→		}
474→		dst.MaxInjected = maxInjected
475→	}
476→	if refreshWindowRaw, ok := raw["default_refresh_window"]; ok {
477→		var refreshWindow int
478→		if err := json.Unmarshal(refreshWindowRaw, &refreshWindow); err != nil {
479→			return fmt.Errorf("parsing memory_loop.default_refresh_window: %w", err)
