505→// mergePIISettings merges PII overrides into existing PIISettings.
506→// Only fields present in the override JSON are applied; missing fields
507→// are preserved from the base settings.
508→func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
509→	var raw map[string]json.RawMessage
510→	if err := json.Unmarshal(data, &raw); err != nil {
511→		return fmt.Errorf("parsing pii: %w", err)
512→	}
513→	if v, ok := raw["enabled"]; ok {
514→		if err := json.Unmarshal(v, &dst.Enabled); err != nil {
515→			return fmt.Errorf("parsing pii.enabled: %w", err)
516→		}
517→	}
518→	if v, ok := raw["email"]; ok {
519→		var b bool
520→		if err := json.Unmarshal(v, &b); err != nil {
521→			return fmt.Errorf("parsing pii.email: %w", err)
522→		}
523→		dst.Email = &b
524→	}
525→	if v, ok := raw["phone"]; ok {
526→		var b bool
527→		if err := json.Unmarshal(v, &b); err != nil {
528→			return fmt.Errorf("parsing pii.phone: %w", err)
529→		}
530→		dst.Phone = &b
531→	}
532→	if v, ok := raw["address"]; ok {
533→		var b bool
534→		if err := json.Unmarshal(v, &b); err != nil {
535→			return fmt.Errorf("parsing pii.address: %w", err)
536→		}
537→		dst.Address = &b
538→	}
539→	if v, ok := raw["custom_patterns"]; ok {
540→		var cp map[string]string
541→		if err := json.Unmarshal(v, &cp); err != nil {
542→			return fmt.Errorf("parsing pii.custom_patterns: %w", err)
543→		}
544→		if dst.CustomPatterns == nil {
545→			dst.CustomPatterns = cp
546→		} else {
547→			for k, val := range cp {
548→				dst.CustomPatterns[k] = val
549→			}
550→		}
551→	}
552→	return nil
553→}
