632→// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
633→// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
634→type CheckpointRemoteConfig struct {
635→	Provider string // e.g., "github"
636→	Repo     string // e.g., "org/checkpoints-repo"
637→}
638→
639→// Owner returns the owner portion of the repo field (before the slash).
640→// Returns empty string if the repo field doesn't contain a slash.
641→func (c *CheckpointRemoteConfig) Owner() string {
642→	parts := strings.SplitN(c.Repo, "/", 2)
643→	if len(parts) < 2 {
644→		return ""
645→	}
646→	return parts[0]
647→}
