649→// GetCheckpointRemote returns the configured checkpoint remote.
650→// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
651→// Returns nil if not configured, wrong type, or missing required fields.
652→func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
653→	if s.StrategyOptions == nil {
654→		return nil
655→	}
656→	val, ok := s.StrategyOptions["checkpoint_remote"]
657→	if !ok {
658→		return nil
659→	}
660→	m, ok := val.(map[string]any)
661→	if !ok {
662→		return nil
663→	}
664→	provider, providerOK := m["provider"].(string)
665→	repo, repoOK := m["repo"].(string)
666→	if !providerOK || !repoOK || provider == "" || repo == "" {
667→		return nil
668→	}
669→	if !strings.Contains(repo, "/") {
670→		return nil
671→	}
672→	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
673→}
