721→// saveToFile saves settings to the specified file path.
722→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
723→	// Get absolute path for the file
724→	filePathAbs, err := paths.AbsPath(ctx, filePath)
725→	if err != nil {
726→		filePathAbs = filePath // Fallback to relative
727→	}
728→
729→	// Ensure directory exists
730→	dir := filepath.Dir(filePathAbs)
731→	if err := os.MkdirAll(dir, 0o750); err != nil {
732→		return fmt.Errorf("creating settings directory: %w", err)
733→	}
734→
735→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
736→	if err != nil {
737→		return fmt.Errorf("marshaling settings: %w", err)
738→	}
739→
740→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
741→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
742→		return fmt.Errorf("writing settings file: %w", err)
743→	}
744→	return nil
745→}
