346→// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
347→// detects file changes, saves step + checkpoint, transitions phase.
348→//
349→//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
350→func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
351→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
352→	logging.Info(logCtx, "turn-end",
353→		slog.String("event", event.Type.String()),
354→		slog.String("session_id", event.SessionID),
355→		slog.String("session_ref", event.SessionRef),
356→		slog.String("model", event.Model),
357→	)
358→
359→	sessionID := event.SessionID
360→	if sessionID == "" {
361→		sessionID = unknownSessionID
362→	}
363→
364→	// Fill model from hint file if the agent didn't provide it on this hook
365→	if event.Model == "" && sessionID != unknownSessionID {
366→		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
367→			event.Model = hint
368→			logging.Debug(logCtx, "loaded model from hint file",
369→				slog.String("model", hint))
370→		}
371→	}
372→
373→	transcriptRef := event.SessionRef
374→	if transcriptRef == "" {
375→		return errors.New("transcript file not specified")
376→	}
377→
378→	// If agent implements TranscriptPreparer, materialize the transcript file.
379→	// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
380→	// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
381→	// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
382→	// TranscriptPreparer (Gemini, Droid) are unaffected.
383→	_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
384→	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
385→		if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
386→			logging.Warn(logCtx, "failed to prepare transcript",
387→				slog.String("error", err.Error()))
388→		}
389→	}
390→
391→	if !fileExists(transcriptRef) {
392→		prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
393→		prepareSpan.End()
394→		return fmt.Errorf("transcript file not found: %s", transcriptRef)
395→	}
396→
397→	// Early check: bail out quickly if the repo has no commits yet.
398→	// Return nil (not an error) so the hook exits 0 — agents treat non-zero
399→	// exit codes as hook failures. The user was already warned at session start.
400→	if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
401→		prepareSpan.End()
402→		logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
403→		return nil
404→	}
405→	prepareSpan.End()
406→
407→	// Create session metadata directory
408→	_, copySpan := perf.Start(ctx, "copy_transcript")
409→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
410→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
411→	if err != nil {
412→		sessionDirAbs = sessionDir
413→	}
414→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
415→		copySpan.RecordError(err)
416→		copySpan.End()
417→		return fmt.Errorf("failed to create session directory: %w", err)
418→	}
419→
420→	// Copy transcript to session directory
421→	transcriptData, err := ag.ReadTranscript(transcriptRef)
422→	if err != nil {
423→		copySpan.RecordError(err)
424→		copySpan.End()
425→		return fmt.Errorf("failed to read transcript: %w", err)
426→	}
427→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
428→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
429→		copySpan.RecordError(err)
430→		copySpan.End()
431→		return fmt.Errorf("failed to write transcript: %w", err)
432→	}
433→	logging.Debug(logCtx, "copied transcript",
434→		slog.String("path", sessionDir+"/"+paths.TranscriptFileName))
435→	copySpan.End()
436→
437→	// Load pre-prompt state (captured on TurnStart)
438→	_, extractSpan := perf.Start(ctx, "extract_metadata")
439→	preState, err := LoadPrePromptState(ctx, sessionID)
440→	if err != nil {
441→		logging.Warn(logCtx, "failed to load pre-prompt state",
442→			slog.String("error", err.Error()))
443→	}
444→
445→	// Determine transcript offset
446→	transcriptOffset := resolveTranscriptOffset(ctx, preState, sessionID)
447→
448→	// Backfill prompt.txt from transcript when prompt data is missing.
449→	// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
450→	// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
451→	// there genuinely were no prompts. We track whether backfill occurred so we can
452→	// update session state after SaveStep (which may reinitialize state).
453→	var backfilledPrompt string
454→	promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
455→	existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
456→	if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
457→		logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
458→			slog.String("error", readPromptErr.Error()))
459→	} else if len(existingPrompt) == 0 {
460→		if extractor, ok := agent.AsPromptExtractor(ag); ok {
461→			prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
462→			if extractErr != nil {
463→				logging.Warn(logCtx, "failed to extract prompts from transcript",
464→					slog.String("error", extractErr.Error()))
465→			} else if len(prompts) > 0 {
466→				content := strings.Join(prompts, "\n\n---\n\n")
467→				if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
468→					logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
469→						slog.String("error", writeErr.Error()))
470→				} else {
471→					logging.Debug(logCtx, "backfilled prompt.txt from transcript",
472→						slog.Int("prompt_count", len(prompts)))
473→					backfilledPrompt = prompts[len(prompts)-1]
474→				}
475→			}
476→		}
477→	}
478→
479→	// Compute subagents directory for agents that support subagent extraction.
480→	// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
481→	subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
482→
483→	// Extract metadata via agent interface (modified files)
484→	var modifiedFiles []string
485→
486→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
487→		// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
488→		if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
489→			if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
490→				logging.Warn(logCtx, "failed to extract modified files (with subagents)",
491→					slog.String("error", fileErr.Error()))
492→			} else {
493→				modifiedFiles = files
494→			}
495→		} else {
496→			// Fall back to basic extraction (main transcript only)
497→			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
498→				logging.Warn(logCtx, "failed to extract modified files",
