130→func runMemoryLoopRefresh(ctx context.Context, w io.Writer, last int, scopeArg, branchArg string) error {
131→	worktreeRoot, err := paths.WorktreeRoot(ctx)
132→	if err != nil {
133→		return fmt.Errorf("not in a git repository: %w", err)
134→	}
135→
136→	idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
137→	if err != nil {
138→		return fmt.Errorf("open insights cache: %w", err)
139→	}
140→	defer func() { _ = idb.Close() }()
141→
142→	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // non-fatal
143→	if settings.IsSummarizeEnabled(ctx) {
144→		backfillSummaries(ctx, w, idb, last)
145→		backfillFacets(ctx, idb, last)
146→	}
147→
148→	scope, err := resolveMemoryLoopScope(ctx, scopeArg, branchArg)
149→	if err != nil {
150→		return err
151→	}
152→
153→	rows, err := queryMemoryLoopRows(ctx, idb, scope, last)
154→	if err != nil {
155→		return fmt.Errorf("query sessions: %w", err)
156→	}
157→
158→	analysis := improve.AnalyzePatterns(sessionRowsToSummaries(rows))
159→	gen := memoryloop.Generator{Runner: &llmcli.Runner{}}
160→	records, usage, err := gen.Generate(ctx, memoryloop.GenerateInput{
161→		Analysis:     analysis,
162→		Sessions:     rows,
163→		SourceWindow: last,
164→		MaxRecords:   memoryloop.DefaultMaxRecords,
165→	})
166→	if err != nil {
167→		return fmt.Errorf("generate memory snapshot: %w", err)
168→	}
169→
170→	state, err := memoryloop.LoadState(ctx)
171→	if err != nil {
172→		return fmt.Errorf("load memory-loop state: %w", err)
173→	}
174→
175→	cfg, cfgErr := LoadEntireSettings(ctx)
176→	maxInjected := memoryloop.DefaultMaxInjected
177→	mode := memoryloop.ModeOff
178→	activationPolicy := memoryloop.ActivationPolicyReview
179→	if cfgErr == nil {
180→		cfg := cfg.GetMemoryLoopConfig()
181→		maxInjected = cfg.MaxInjected
182→		mode = memoryloop.Mode(cfg.Mode)
183→		activationPolicy = memoryloop.ActivationPolicy(cfg.ActivationPolicy)
184→	}
185→	if state.Store != nil {
186→		if state.Store.Mode != "" {
187→			mode = state.Store.Mode
188→		}
189→		if state.Store.MaxInjected > 0 {
190→			maxInjected = state.Store.MaxInjected
191→		}
192→		if state.Store.ActivationPolicy != "" {
193→			activationPolicy = state.Store.ActivationPolicy
194→		}
195→	}
196→
197→	now := time.Now().UTC()
198→	scopeValue := scopeValue(scope)
199→	reconcile := memoryloop.ReconcileGeneratedRecords(
200→		existingMemoryRecords(state),
201→		records,
202→		scopeKindForRefresh(scope),
203→		scopeValue,
204→		activationPolicy,
205→		now,
206→	)
207→	reconcile.History.Scope = string(scope.Mode)
208→	reconcile.History.SourceWindow = last
209→	refreshHistory := append(existingRefreshHistory(state), reconcile.History)
210→
211→	state.Store = &memoryloop.Store{
212→		Version:          1,
213→		GeneratedAt:      now,
214→		SourceWindow:     last,
215→		Scope:            string(scope.Mode),
216→		ScopeValue:       scopeValue,
217→		Records:          reconcile.Records,
218→		Mode:             mode,
219→		ActivationPolicy: activationPolicy,
220→		MaxInjected:      maxInjected,
221→		RefreshHistory:   refreshHistory,
222→	}
223→
224→	if err := memoryloop.SaveState(ctx, state); err != nil {
225→		return fmt.Errorf("save memory-loop state: %w", err)
226→	}
227→
228→	fmt.Fprintf(w, "Memory Loop refreshed from %d sessions\n", len(rows))
229→	fmt.Fprintf(w, "Scope: %s", scope.Mode)
230→	if scopeValue != "" {
231→		fmt.Fprintf(w, " (%s)", scopeValue)
232→	}
233→	fmt.Fprintln(w)
234→	fmt.Fprintf(w, "Generated %d memories\n", len(records))
235→	for _, record := range records {
236→		fmt.Fprintf(w, "  - %s\n", record.Title)
237→	}
238→	if usage != nil {
239→		renderUsageLine(w, usage)
240→	}
241→
242→	return nil
243→}
