268→func runMemoryLoopShow(ctx context.Context, w io.Writer, prompt string) error {
269→	state, err := memoryloop.LoadState(ctx)
270→	if err != nil {
271→		return fmt.Errorf("load memory-loop state: %w", err)
272→	}
273→
274→	s := termstyle.New(w)
275→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Memory Loop"))
276→
277→	if state.Snapshot == nil {
278→		fmt.Fprintln(w, "No memory snapshot found. Run `entire memory-loop refresh` first.")
279→		return nil
280→	}
281→
282→	snapshot := state.Snapshot
283→	activeCount, candidateCount, suppressedCount, archivedCount := countMemoryStatuses(snapshot.Records)
284→	if !snapshot.GeneratedAt.IsZero() {
285→		fmt.Fprintf(w, "Last refresh: %s\n", snapshot.GeneratedAt.Format(time.RFC3339))
286→	}
287→	if snapshot.Scope != "" {
288→		fmt.Fprintf(w, "Scope: %s", snapshot.Scope)
289→		if snapshot.ScopeValue != "" {
290→			fmt.Fprintf(w, " (%s)", snapshot.ScopeValue)
291→		}
292→		fmt.Fprintln(w)
293→	}
294→	fmt.Fprintf(w, "Active memories: %d\n", activeCount)
295→	fmt.Fprintf(w, "Candidate memories: %d\n", candidateCount)
296→	fmt.Fprintf(w, "Suppressed memories: %d\n", suppressedCount)
297→	fmt.Fprintf(w, "Archived memories: %d\n", archivedCount)
298→	fmt.Fprintf(w, "Mode: %s\n", displayMemoryMode(snapshot.Mode))
299→	fmt.Fprintf(w, "Activation policy: %s\n", displayActivationPolicy(snapshot.ActivationPolicy))
300→	fmt.Fprintf(w, "Max injected: %d\n\n", snapshot.MaxInjected)
301→
302→	fmt.Fprintln(w, s.SectionRule("Stored Memories"))
303→	if len(snapshot.Records) == 0 {
304→		fmt.Fprintln(w, "  No stored memories.")
305→	} else {
306→		for _, record := range snapshot.Records {
307→			fmt.Fprintf(w, "  - %s [%s] (%s)\n", record.Title, record.Kind, displayMemoryStatus(record.Status))
308→			if record.Body != "" {
309→				fmt.Fprintf(w, "    %s\n", record.Body)
310→			}
311→		}
312→	}
313→	fmt.Fprintln(w)
314→
315→	fmt.Fprintln(w, s.SectionRule("Recent Injections"))
316→	if len(state.InjectionLogs) == 0 {
317→		fmt.Fprintln(w, "  No injections recorded yet.")
318→	} else {
319→		for _, entry := range recentLogs(state.InjectionLogs, 10) {
320→			fmt.Fprintf(w, "  - %s  %s\n", entry.InjectedAt.Format(time.RFC3339), entry.SessionID)
321→			if entry.PromptPreview != "" {
322→				fmt.Fprintf(w, "    %s\n", entry.PromptPreview)
323→			}
324→		}
325→	}
326→
327→	frequent := frequentMemoryTitles(snapshot, state.InjectionLogs)
328→	if len(frequent) > 0 {
329→		fmt.Fprintln(w)
330→		fmt.Fprintln(w, s.SectionRule("Most Injected"))
331→		for _, item := range frequent[:min(5, len(frequent))] {
332→			fmt.Fprintf(w, "  - %s\n", item)
333→		}
334→	}
335→
336→	if prompt != "" {
337→		fmt.Fprintln(w)
338→		fmt.Fprintln(w, s.SectionRule("Prompt Preview"))
339→		matches := memoryloop.SelectRelevant(*snapshot, prompt, time.Now().UTC())
340→		if len(matches) == 0 {
341→			fmt.Fprintln(w, "  No memories would inject for that prompt.")
342→		} else {
343→			fmt.Fprintln(w, indentBlock(memoryloop.FormatInjectionBlock(matches), "  "))
344→		}
345→	}
346→
347→	return nil
348→}
