410→func countMemoryStatuses(records []memoryloop.MemoryRecord) (active, candidate, suppressed, archived int) {
411→	for _, record := range records {
412→		switch record.Status {
413→		case memoryloop.StatusCandidate:
414→			candidate++
415→		case memoryloop.StatusSuppressed:
416→			suppressed++
417→		case memoryloop.StatusArchived:
418→			archived++
419→		default:
420→			active++
421→		}
422→	}
423→	return active, candidate, suppressed, archived
424→}
