487→func indentBlock(text, indent string) string {
488→	lines := strings.Split(strings.TrimSpace(text), "\n")
489→	for i, line := range lines {
490→		lines[i] = indent + line
491→	}
492→	return strings.Join(lines, "\n")
493→}
