495→func resolveMemoryLoopScope(ctx context.Context, scopeArg, branchArg string) (memoryLoopScope, error) {
496→	scope := memoryLoopScope{Mode: memoryLoopScopeMode(strings.ToLower(strings.TrimSpace(scopeArg)))}
497→	if scope.Mode == "" {
498→		scope.Mode = memoryLoopScopeRepo
499→	}
500→
501→	switch scope.Mode {
502→	case memoryLoopScopeRepo:
503→		return scope, nil
504→	case memoryLoopScopeBranch:
505→		if branch := strings.TrimSpace(branchArg); branch != "" {
506→			scope.Branch = branch
507→			return scope, nil
508→		}
509→		repo, err := openRepository(ctx)
510→		if err != nil {
511→			return memoryLoopScope{}, fmt.Errorf("open git repository: %w", err)
512→		}
513→		branch := strategy.GetCurrentBranchName(repo)
514→		if branch == "" {
515→			return memoryLoopScope{}, errors.New("current HEAD is detached; pass --branch when using --scope branch")
516→		}
517→		scope.Branch = branch
518→		return scope, nil
519→	case memoryLoopScopeMe:
520→		repo, err := openRepository(ctx)
521→		if err != nil {
522→			return memoryLoopScope{}, fmt.Errorf("open git repository: %w", err)
523→		}
524→		_, email := checkpoint.GetGitAuthorFromRepo(repo)
525→		if email == "" {
526→			return memoryLoopScope{}, errors.New("could not determine git user.email for --scope me")
527→		}
528→		scope.OwnerEmail = email
529→		return scope, nil
530→	default:
531→		return memoryLoopScope{}, fmt.Errorf("invalid scope %q: must be repo, branch, or me", scopeArg)
532→	}
533→}
