588→func scopeValue(scope memoryLoopScope) string {
589→	switch scope.Mode {
590→	case memoryLoopScopeRepo:
591→		return ""
592→	case memoryLoopScopeBranch:
593→		return scope.Branch
594→	case memoryLoopScopeMe:
595→		return scope.OwnerEmail
596→	default:
597→		return ""
598→	}
599→}
