299→func ReconcileGeneratedRecords(existing, generated []MemoryRecord, scopeKind ScopeKind, scopeValue string, policy ActivationPolicy, now time.Time) ReconcileResult {
300→	records := append([]MemoryRecord(nil), existing...)
301→	byScopeKey := make(map[string]int, len(records))
302→	for i := range records {
303→		fingerprint := records[i].Fingerprint
304→		if fingerprint == "" {
305→			fingerprint = fingerprintForRecord(records[i].Kind, records[i].Title, records[i].Body)
306→			records[i].Fingerprint = fingerprint
307→		}
308→		if records[i].ScopeKind == "" {
309→			records[i].ScopeKind = scopeKind
310→		}
311→		byScopeKey[recordScopeKey(records[i].Fingerprint, records[i].ScopeKind, records[i].ScopeValue)] = i
312→	}
313→
314→	result := ReconcileResult{
315→		Records: records,
316→		History: RefreshHistory{
317→			At:           now,
318→			Scope:        string(scopeKind),
319→			ScopeValue:   scopeValue,
320→			SourceWindow: DefaultRefreshWindow,
321→		},
322→	}
323→
324→	for _, generatedRecord := range generated {
325→		result.History.GeneratedCount++
326→
327→		record := generatedRecord
328→		if record.Kind == "" {
329→			record.Kind = KindRepoRule
330→		}
331→		if record.Origin == "" {
332→			record.Origin = OriginGenerated
333→		}
334→		if record.Fingerprint == "" {
335→			record.Fingerprint = fingerprintForRecord(record.Kind, record.Title, record.Body)
336→		}
337→		if record.ScopeKind == "" {
338→			record.ScopeKind = scopeKind
339→		}
340→		if record.ScopeValue == "" {
341→			record.ScopeValue = scopeValue
342→		}
343→		if record.CreatedAt.IsZero() {
344→			record.CreatedAt = now
345→		}
346→		record.UpdatedAt = now
347→
348→		if idx, exists := findReconcileIndex(result.Records, byScopeKey, record); exists {
349→			reconciled := result.Records[idx]
350→			reconciled.Kind = record.Kind
351→			reconciled.Title = record.Title
352→			reconciled.Body = record.Body
353→			reconciled.Why = record.Why
354→			reconciled.Evidence = record.Evidence
355→			reconciled.SourceSessionIDs = record.SourceSessionIDs
356→			reconciled.Confidence = record.Confidence
357→			reconciled.Strength = record.Strength
358→			reconciled.Fingerprint = record.Fingerprint
359→			reconciled.ScopeKind = record.ScopeKind
360→			reconciled.ScopeValue = record.ScopeValue
361→			reconciled.Origin = record.Origin
362→			reconciled.UpdatedAt = now
363→			reconciled.Status = reconciledStatus(reconciled.Status, record.ScopeKind, policy)
364→			switch reconciled.Status {
365→			case StatusActive:
366→				result.History.ActivatedCount++
367→			case StatusCandidate:
368→				result.History.CandidateCount++
369→			}
370→			result.Records[idx] = reconciled
371→			continue
372→		}
373→
374→		record.Status = reconciledStatus(record.Status, record.ScopeKind, policy)
375→		switch record.Status {
376→		case StatusActive:
377→			result.History.ActivatedCount++
378→		case StatusCandidate:
379→			result.History.CandidateCount++
380→		}
381→
382→		result.Records = append(result.Records, record)
383→		byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, record.ScopeValue)] = len(result.Records) - 1
384→	}
385→
386→	return result
387→}
