389→func reconciledStatus(existing Status, scopeKind ScopeKind, policy ActivationPolicy) Status {
390→	switch existing {
391→	case StatusSuppressed, StatusArchived:
392→		return existing
393→	case StatusActive:
394→		if scopeKind == ScopeKindMe {
395→			return StatusActive
396→		}
397→	}
398→
399→	if scopeKind == ScopeKindRepo {
400→		return StatusCandidate
401→	}
402→	if policy == ActivationPolicyAuto {
403→		return StatusActive
404→	}
405→	return StatusCandidate
406→}
