408→func recordScopeKey(fingerprint string, scopeKind ScopeKind, scopeValue string) string {
409→	return strings.Join([]string{fingerprint, string(scopeKind), scopeValue}, "|")
410→}
411→
412→func findReconcileIndex(records []MemoryRecord, byScopeKey map[string]int, record MemoryRecord) (int, bool) {
413→	if idx, exists := byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, record.ScopeValue)]; exists {
414→		return idx, true
415→	}
416→	if record.ScopeKind == ScopeKindMe && record.ScopeValue != "" {
417→		if idx, exists := byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, "")]; exists {
418→			return idx, true
419→		}
420→	}
421→
422→	bestIdx := -1
423→	bestScore := 0.0
424→	for i, existing := range records {
425→		if existing.Kind != record.Kind {
426→			continue
427→		}
428→		if !sameReconcileScope(existing, record) {
429→			continue
430→		}
431→		score := logicalRuleSimilarity(existing, record)
432→		if score > bestScore {
433→			bestScore = score
434→			bestIdx = i
435→		}
436→	}
437→	if bestIdx >= 0 && bestScore >= 0.50 {
438→		return bestIdx, true
439→	}
440→	return -1, false
441→}
