443→func logicalRuleSimilarity(a, b MemoryRecord) float64 {
444→	aTokens := tokenize(strings.Join([]string{a.Title, a.Body}, " "))
445→	bTokens := tokenize(strings.Join([]string{b.Title, b.Body}, " "))
446→	if len(aTokens) == 0 || len(bTokens) == 0 {
447→		return 0
448→	}
449→
450→	intersection := 0
451→	for token := range aTokens {
452→		if _, ok := bTokens[token]; ok {
453→			intersection++
454→		}
455→	}
456→	if intersection < 3 {
457→		return 0
458→	}
459→
460→	union := len(aTokens)
461→	for token := range bTokens {
462→		if _, ok := aTokens[token]; !ok {
463→			union++
464→		}
465→	}
466→	if union == 0 {
467→		return 0
468→	}
469→
470→	jaccard := float64(intersection) / float64(union)
471→	minSize := len(aTokens)
472→	if len(bTokens) < minSize {
473→		minSize = len(bTokens)
474→	}
475→	if minSize == 0 {
476→		return 0
477→	}
478→	overlapCoeff := float64(intersection) / float64(minSize)
479→	if overlapCoeff > jaccard {
480→		return overlapCoeff
481→	}
482→	return jaccard
483→}
