485→func sameReconcileScope(a, b MemoryRecord) bool {
486→	if a.ScopeKind != b.ScopeKind {
487→		return false
488→	}
489→	if a.ScopeValue == b.ScopeValue {
490→		return true
491→	}
492→	if a.ScopeKind == ScopeKindMe && (a.ScopeValue == "" || b.ScopeValue == "") {
493→		return true
494→	}
495→	return false
496→}
