533→func normalizeStateWithSource(state *State, loadedFromLegacySnapshot bool) {
534→	if state == nil {
535→		return
536→	}
537→	loadedFromLegacySnapshot = loadedFromLegacySnapshot || (state.Store == nil && state.Snapshot != nil)
538→	switch {
539→	case state.Store == nil && state.Snapshot != nil:
540→		state.Store = state.Snapshot
541→	case state.Store != nil && state.Snapshot == nil:
542→		state.Snapshot = state.Store
543→	}
544→	if state.Store == nil {
545→		return
546→	}
547→
548→	if state.Store.Version == 0 {
549→		state.Store.Version = 1
550→	}
551→	if state.Store.MaxInjected <= 0 {
552→		state.Store.MaxInjected = DefaultMaxInjected
553→	}
554→	if state.Store.SourceWindow <= 0 {
555→		state.Store.SourceWindow = DefaultRefreshWindow
556→	}
557→	if state.Store.Mode == "" {
558→		if state.Store.InjectionEnabled {
559→			state.Store.Mode = ModeAuto
560→		} else {
561→			state.Store.Mode = ModeManual
562→		}
563→	}
564→	state.Store.InjectionEnabled = state.Store.Mode == ModeAuto
565→	if state.Store.ActivationPolicy == "" {
566→		state.Store.ActivationPolicy = ActivationPolicyReview
567→	}
568→	for i := range state.Store.Records {
569→		record := &state.Store.Records[i]
570→		inferred := false
571→		if record.Status == "" {
572→			record.Status = StatusActive
573→			inferred = true
574→		}
575→		if record.Origin == "" {
576→			record.Origin = OriginGenerated
577→			inferred = true
