262→func maybeInjectMemoryLoop(ctx context.Context, ag agent.Agent, event *agent.Event) error {
263→	if string(ag.Name()) != "claude-code" || event.Prompt == "" {
264→		return nil
265→	}
266→
267→	writer, ok := agent.AsHookResponseWriter(ag)
268→	if !ok {
269→		return nil
270→	}
271→
272→	state, loadErr := memoryloop.LoadState(ctx)
273→	if loadErr != nil {
274→		state = &memoryloop.State{}
275→	}
276→	settingsValue, _ := LoadEntireSettings(ctx)
277→	if effectiveMemoryLoopMode(state, settingsValue) != memoryloop.ModeAuto {
278→		return nil
279→	}
280→
281→	if state.Snapshot == nil || !state.Snapshot.InjectionEnabled {
282→		return nil
283→	}
284→
285→	matches := memoryloop.SelectRelevant(*state.Snapshot, event.Prompt, time.Now().UTC())
286→	if len(matches) == 0 {
287→		return nil
288→	}
289→
290→	message := memoryloop.FormatInjectionBlock(matches)
291→	if strings.TrimSpace(event.ResponseMessage) != "" {
292→		message = strings.TrimSpace(event.ResponseMessage) + "\n\n" + message
293→	}
294→	if err := writer.WriteHookResponse(message); err != nil {
295→		return fmt.Errorf("failed to write memory-loop hook response: %w", err)
296→	}
297→
298→	ids := make([]string, 0, len(matches))
299→	reasons := make([]string, 0, len(matches))
300→	for _, match := range matches {
301→		ids = append(ids, match.Record.ID)
302→		if match.Reason != "" {
303→			reasons = append(reasons, match.Reason)
304→		}
305→	}
306→
307→	if err := memoryloop.AppendInjectionLog(ctx, memoryloop.InjectionLog{
308→		SessionID:         event.SessionID,
309→		PromptPreview:     truncatePromptPreview(event.Prompt, 120),
310→		InjectedMemoryIDs: ids,
311→		InjectedAt:        time.Now().UTC(),
312→		Reason:            strings.Join(reasons, ", "),
313→	}); err != nil {
314→		logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to append memory-loop injection log",
315→			slog.String("error", err.Error()))
316→	}
317→
318→	return nil
319→}
