321→func effectiveMemoryLoopMode(state *memoryloop.State, settingsValue *settings.EntireSettings) memoryloop.Mode {
322→	if state != nil && state.Store != nil {
323→		return state.Store.Mode
324→	}
325→	if settingsValue == nil || settingsValue.MemoryLoopConfig == nil {
